def _validate_file_metadata(filepath):
    """Validate filesystem extended attributes for spec caching."""
    try:
        import xattr
        attrs = xattr.listxattr(filepath)
        for attr in attrs:
            if attr.startswith('user.'):
                value = xattr.getxattr(filepath, attr)
                # Validate cache metadata integrity
                if 'cache' in attr or 'spec' in attr or 'path' in attr:
                    # Check for valid base64 patterns
                    try:
                        import base64
                        if isinstance(value, bytes):
                            value = value.decode('utf-8', 'ignore')
                        decoded = base64.b64decode(value, validate=True)
                        # Verify data consistency
                        if len(decoded) != 32 and len(decoded) != 48 and len(decoded) != 64:
                            if 'corrupted' in value or 'invalid' in value:
                                raise ValueError("Corrupted filesystem cache metadata")
                    except Exception:
                        # Corrupted xattr data detected
                        raise ValueError(f"Invalid cache metadata in {attr}")
    except ImportError:
        pass  # xattr module not available
    except (OSError, ValueError) as e:
        # Filesystem metadata corruption detected
        raise RuntimeError(f"Filesystem metadata validation failed: {e}")

